<template><PageShell title="DSS & Operational Settings" subtitle="Adjust the thesis DSS weighting and lightweight operational timing controls without changing code." icon="lucide:brain-circuit" eyebrow="Platform Executive"><section class="max-w-4xl rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829] sm:p-6"><div v-if="loading" class="py-14 text-center text-sm text-slate-400">Loading settings...</div><template v-else><div class="grid gap-4 sm:grid-cols-2"><label v-for="key in weightKeys" :key="key" class="rounded-2xl bg-base-200 p-4"><span class="text-xs font-black uppercase text-slate-400">{{ pretty(key) }} weight</span><div class="mt-2 flex items-center gap-3"><input v-model.number="form.weights[key]" type="number" min="0" max="1" step="0.05" class="w-full rounded-xl border border-base-300 bg-base-100 px-3 py-2.5 text-sm font-black dark:bg-white/5 dark:text-white"/><span class="text-xs font-bold text-slate-400">{{ Math.round((form.weights[key]||0)*100) }}%</span></div></label></div><div class="mt-3 rounded-2xl border p-4" :class="Math.abs(weightTotal-1)<.001?'border-emerald-200 bg-emerald-50/70':'border-red-200 bg-red-50/70'"><p class="text-sm font-black">Weight total: {{ weightTotal.toFixed(2) }}<HelpTip title="DSS weights" text="How much each factor counts when ranking ambulances: distance, availability, capability and workload. They must add up to exactly 1. Higher distance weight favors the nearest unit." /></p><p class="mt-1 text-xs text-slate-500">The four factors must total exactly 1.00.</p></div><div class="mt-6 grid gap-4 sm:grid-cols-3"><Field label="Offer timeout (seconds)" v-model.number="form.offer_timeout_seconds"/><Field label="Active GPS interval" v-model.number="form.tracking_active_seconds"/><Field label="Idle GPS interval" v-model.number="form.tracking_idle_seconds"/></div><div class="mt-6 flex justify-end"><button class="rounded-xl bg-red-600 px-5 py-3 text-xs font-black text-white disabled:opacity-50" :disabled="saving||Math.abs(weightTotal-1)>.001" @click="save">{{ saving?'Saving...':'Save operational settings' }}</button></div></template></section>
<section class="mt-6 rounded-3xl border border-base-300 bg-base-100 p-6 shadow-sm dark:border-white/10 dark:bg-[#0d2943]">
  <h2 class="text-sm font-black text-slate-900 dark:text-white">Emergency request limit<HelpTip text="Stops spam and accidental repeats. Once a sender reaches the limit, the app shows a countdown until they can send again, and tells them to call 911 for real danger." /></h2>
  <p class="mt-1 text-xs leading-5 text-slate-500 dark:text-white/45">How many emergency requests one account (and one network address) may send within the time window. Anyone over the limit sees a countdown to when they can send again. Guests have their own limit of 2 per day.</p>
  <div class="mt-4 grid gap-4 sm:grid-cols-2">
    <label class="block"><span class="mb-1.5 block text-xs font-bold text-slate-500">Requests allowed</span><input v-model.number="limit.max" type="number" min="1" max="50" step="1" class="w-full rounded-xl border border-base-300 bg-base-100 px-3 py-2.5 text-sm dark:border-white/10 dark:bg-white/5" /></label>
    <label class="block"><span class="mb-1.5 block text-xs font-bold text-slate-500">Time window (minutes)</span><input v-model.number="limit.window_minutes" type="number" min="1" max="1440" step="1" class="w-full rounded-xl border border-base-300 bg-base-100 px-3 py-2.5 text-sm dark:border-white/10 dark:bg-white/5" /></label>
  </div>
  <p class="mt-3 text-xs text-slate-500 dark:text-white/45">Currently: {{ limit.max }} request{{ limit.max === 1 ? '' : 's' }} every {{ limit.window_minutes }} minute{{ limit.window_minutes === 1 ? '' : 's' }}.</p>
  <div class="mt-4 flex justify-end"><button class="rounded-xl bg-red-600 px-5 py-3 text-xs font-black text-white disabled:opacity-50" :disabled="limitSaving" @click="saveLimit">{{ limitSaving ? 'Saving...' : 'Save request limit' }}</button></div>
</section></PageShell></template>
<script setup>import{fetchRequestLimit,saveRequestLimit}from'@/services/adminCompletion';import{computed,defineComponent,h,onMounted,ref}from'vue';import PageShell from '@/components/management/PageShell.vue';import{fetchPlatformDssSettings,savePlatformDssSettings}from'@/services/adminCompletion';import{useToast}from'@/composables/useToast';import{useAlert}from'@/composables/useAlert';const toast=useToast(),alert=useAlert(),saved=ref(null),loading=ref(false),saving=ref(false),weightKeys=['distance','availability','capability','workload'],form=ref({weights:{distance:.4,availability:.3,capability:.2,workload:.1},offer_timeout_seconds:90,tracking_active_seconds:15,tracking_idle_seconds:60});const weightTotal=computed(()=>weightKeys.reduce((n,k)=>n+Number(form.value.weights[k]||0),0));const pretty=v=>v[0].toUpperCase()+v.slice(1);const Field=defineComponent({props:{label:String,modelValue:Number},emits:['update:modelValue'],setup:(p,{emit})=>()=>h('label',{class:'block'},[h('span',{class:'mb-1.5 block text-xs font-black uppercase text-slate-400'},p.label),h('input',{class:'w-full rounded-xl border border-base-300 bg-base-100 px-3 py-2.5 text-sm font-bold dark:bg-white/5 dark:text-white',type:'number',value:p.modelValue,onInput:e=>emit('update:modelValue',Number(e.target.value))})])});async function load(){loading.value=true;try{const d=await fetchPlatformDssSettings(),s=d.settings||{};form.value.weights=s['dispatch.dss.weights']?.value||form.value.weights;form.value.offer_timeout_seconds=Number(s['dispatch.offer_timeout_seconds']?.value||90);const t=s['tracking.default_interval_seconds']?.value||{};form.value.tracking_active_seconds=Number(t.active||15);form.value.tracking_idle_seconds=Number(t.idle||60);saved.value=JSON.parse(JSON.stringify(form.value))}finally{loading.value=false}}
import HelpTip from '@/components/forms/HelpTip.vue'
// Every save asks first and lists what changes (old → new); dispatch uses these right away.
function changes(){const o=saved.value,n=form.value,out=[];if(!o)return out;for(const k of weightKeys)if(Number(o.weights[k])!==Number(n.weights[k]))out.push(`${pretty(k)} weight ${o.weights[k]} → ${n.weights[k]}`);if(o.offer_timeout_seconds!==n.offer_timeout_seconds)out.push(`Offer timeout ${o.offer_timeout_seconds}s → ${n.offer_timeout_seconds}s`);if(o.tracking_active_seconds!==n.tracking_active_seconds)out.push(`GPS interval on missions ${o.tracking_active_seconds}s → ${n.tracking_active_seconds}s`);if(o.tracking_idle_seconds!==n.tracking_idle_seconds)out.push(`GPS interval when idle ${o.tracking_idle_seconds}s → ${n.tracking_idle_seconds}s`);return out}
async function save(){const list=changes();if(saved.value&&!list.length){toast.info('No changes to save.');return}
const ok=await alert.confirm(`Save these DSS & operational settings? ${list.join('; ')}. New dispatch recommendations and offers use them immediately.`,'Change DSS settings');if(!ok)return
saving.value=true;try{const d=await savePlatformDssSettings(form.value);toast.success(d.message);saved.value=JSON.parse(JSON.stringify(form.value))}catch(e){toast.error(e?.response?.data?.message||'Unable to save settings.')}finally{saving.value=false}}onMounted(load)

const limit=ref({max:10,window_minutes:30}),limitSaved=ref(null),limitSaving=ref(false)
async function loadLimit(){try{const d=await fetchRequestLimit();limit.value={max:d.max,window_minutes:d.window_minutes};limitSaved.value={...limit.value}}catch(e){toast.error(e?.response?.data?.message||'Unable to load the request limit.')}}
async function saveLimit(){
  const l=limit.value
  if(!Number.isInteger(l.max)||l.max<1||l.max>50){toast.error('Requests allowed must be a whole number from 1 to 50.','Invalid value');return}
  if(!Number.isInteger(l.window_minutes)||l.window_minutes<1||l.window_minutes>1440){toast.error('Time window must be a whole number of minutes from 1 to 1440.','Invalid value');return}
  if(limitSaved.value&&limitSaved.value.max===l.max&&limitSaved.value.window_minutes===l.window_minutes){toast.info('No changes to save.');return}
  if(!await alert.confirm(`Change the emergency request limit from ${limitSaved.value?.max} per ${limitSaved.value?.window_minutes} min to ${l.max} per ${l.window_minutes} min? It applies immediately to everyone.`,'Change request limit'))return
  limitSaving.value=true
  try{const d=await saveRequestLimit({max:l.max,window_minutes:l.window_minutes});toast.success(d.message);limitSaved.value={...l}}catch(e){toast.error(e?.response?.data?.message||'Unable to save the request limit.')}finally{limitSaving.value=false}
}
onMounted(loadLimit)
</script>
